/* ================= КОМПОНЕНТ КРУГОВОЙ ДИАГРАММЫ СТАТИСТИКИ ================= */
const BrandPieChart = ({ data }) => {
  const total = data.reduce((sum, item) => sum + item.value, 0);
  if (total === 0) return <p className={styles.noDataText}>Нет данных для построения диаграммы</p>;

  let currentAngle = 0;
  const colors = [
    '#4a148c', '#7b1fa2', '#9c27b0', '#e91e63', '#673ab7', '#3f51b5',
    '#2196f3', '#00bcd4', '#009688', '#4caf50', '#ffc107', '#ff9800'
  ];

  return (
    <div className={styles.pieChartContainer} style={{ display: 'flex', alignItems: 'center', gap: '2rem', flexWrap: 'wrap', justifyContent: 'center', margin: '2rem 0' }}>
      <svg width="220" height="220" viewBox="0 0 200 200">
        {data.map((item, index) => {
          const percentage = item.value / total;
          const angle = percentage * 360;
          const radius = 50;
          const circumference = 2 * Math.PI * radius;
          const strokeLength = percentage * circumference;
          const strokeOffset = circumference - (currentAngle / 360) * circumference;
          
          currentAngle += angle;
          const color = colors[index % colors.length];

          return (
            <circle
              key={item.name}
              cx="100"
              cy="100"
              r={radius}
              fill="transparent"
              stroke={color}
              strokeWidth="24"
              strokeDasharray={`${strokeLength} ${circumference}`}
              strokeDashoffset={strokeOffset}
              transform="rotate(-90 100 100)"
              style={{ transition: 'all 0.5s ease' }}
            />
          );
        })}
        <circle cx="100" cy="100" r="37" fill="var(--glass-bg, #fff)" />
        <text x="100" y="105" textAnchor="middle" style={{ fontSize: '0.9rem', fontWeight: 'bold', fill: 'var(--text, #000)' }}>
          {total} авто
        </text>
      </svg>
      <div className={styles.pieChartLegend} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.6rem', minWidth: '240px' }}>
        {data.map((item, index) => (
          <div key={item.name} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.85rem' }}>
            <span style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: colors[index % colors.length], display: 'inline-block' }}></span>
            <span style={{ color: 'var(--text)' }}>{item.name}: <strong>{item.value}</strong> ({Math.round((item.value / total) * 100)}%)</span>
          </div>
        ))}
      </div>
    </div>
  );
};

