        const matchesSearch = `${car.brand} ${car.model}`.toLowerCase().includes(carSearch.toLowerCase()) || car.description?.toLowerCase().includes(carSearch.toLowerCase());
        const matchesMinPrice = carMinPrice === '' || car.price >= parseFloat(carMinPrice);
        const matchesMaxPrice = carMaxPrice === '' || car.price <= parseFloat(carMaxPrice);
        const matchesMinYear = carMinYear === '' || car.year >= parseInt(carMinYear);
        const matchesMaxYear = carMaxYear === '' || car.year <= parseInt(carMaxYear);
        return matchesSearch && matchesMinPrice && matchesMaxPrice && matchesMinYear && matchesMaxYear;
      })
      .sort((a, b) => {
        if (!carSortKey) return 0;
        let valA = a[carSortKey];
        let valB = b[carSortKey];
        if (typeof valA === 'string') {
          return carSortDir === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        } else {
          return carSortDir === 'asc' ? valA - valB : valB - valA;
