            <div className={styles.statCard}>
              <h3>Ожидает тест-драйвов</h3>
              <p className={styles.statValue}>{dashboardMetrics.pendingTestDrivesCount}</p>
            </div>
            <div className={styles.statCard}>
              <h3>Активные кредитные заявки</h3>
              <p className={styles.statValue}>{dashboardMetrics.pendingLoansCount}</p>
            </div>
            <div className={styles.statCard}>
              <h3>Оборот одобренных сделок</h3>
              <p className={styles.statValue}>{dashboardMetrics.revenue.toLocaleString()} ₽</p>
            </div>
          </div>

          <div className={styles.chartWrapperCard} style={{ background: 'var(--glass-bg)', padding: '1.5rem', borderRadius: '16px', marginTop: '2rem', boxShadow: '0 8px 32px rgba(0,0,0,0.05)' }}>
            <h3 style={{ fontFamily: 'Playfair Display, serif', textAlign: 'center', marginBottom: '1rem' }}>Статистика по автомобильным брендам</h3>
            <BrandPieChart data={brandPieData} />
          </div>
        </div>
      )}

      {/* ================= ВКЛАДКА: КАТАЛОГ АВТОМОБИЛЕЙ ================= */}
      {activeTab === 'cars' && (
        <div className={styles.catalogManagement}>
          <div className={styles.actionHeader} style={{ display: 'flex', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap', marginBottom: '1.5rem' }}>
            <button className={styles.addBtn} onClick={openAddCarModal}>Добавить автомобиль</button>
            <input
              type="text"
              placeholder="Поиск по марке, модели или описанию..."
              value={carSearch}
              onChange={e => setCarSearch(e.target.value)}
              className={styles.searchInput}
              style={{ padding: '0.6rem 1rem', borderRadius: '10px', border: '1px solid rgba(0,0,0,0.15)', minWidth: '280px' }}
            />
          </div>

          <div className={styles.filterGrid} style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))', gap: '0.8rem', marginBottom: '1.5rem', background: 'rgba(0,0,0,0.02)', padding: '1rem', borderRadius: '12px' }}>
            <input type="number" placeholder="Цена от" value={carMinPrice} onChange={e => setCarMinPrice(e.target.value)} />
            <input type="number" placeholder="Цена до" value={carMaxPrice} onChange={e => setCarMaxPrice(e.target.value)} />
            <input type="number" placeholder="Год от" value={carMinYear} onChange={e => setCarMinYear(e.target.value)} />
            <input type="number" placeholder="Год до" value={carMaxYear} onChange={e => setCarMaxYear(e.target.value)} />
            <button className={styles.resetFiltersBtn} onClick={resetCarFilters}>Сбросить</button>
          </div>

          <div className={styles.tableResponsive}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th onClick={() => handleSort('id')} style={{ cursor: 'pointer' }}>ID</th>
                  <th onClick={() => handleSort('brand')} style={{ cursor: 'pointer' }}>Марка</th>
                  <th onClick={() => handleSort('model')} style={{ cursor: 'pointer' }}>Модель</th>
                  <th onClick={() => handleSort('year')} style={{ cursor: 'pointer' }}>Год</th>
                  <th onClick={() => handleSort('price')} style={{ cursor: 'pointer' }}>Цена</th>
                  <th>Тип кузова</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {filteredCars.map(car => (
                  <tr key={car.id}>
                    <td>{car.id}</td>
                    <td>{car.brand}</td>
                    <td>{car.model}</td>
                    <td>{car.year}</td>
                    <td>{car.price?.toLocaleString()} ₽</td>
                    <td>{bodyTypesRussian[car.body_type] || car.body_type}</td>
                    <td className={styles.actionsCell}>
                      <button className={styles.editBtn} onClick={() => openEditCarModal(car)}>Редактировать</button>
                      <button className={styles.deleteBtn} onClick={() => handleDeleteCar(car.id)}>Удалить</button>
                    </td>
                  </tr>
                ))}
                {filteredCars.length === 0 && (
                  <tr>
                    <td colSpan="7" style={{ textAlign: 'center', padding: '2rem' }}>Автомобили по заданным критериям фильтрации не обнаружены</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ================= ВКЛАДКА: ТЕСТ-ДРАЙВЫ ================= */}
      {activeTab === 'testdrives' && (
        <div className={styles.tableResponsive}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>ID Заявки</th>
                <th>Клиент (Email)</th>
                <th>Автомобиль</th>
                <th>Желаемая дата</th>
                <th>Статус</th>
                <th>Комментарий автосалона</th>
                <th>Действия</th>
              </tr>
            </thead>
            <tbody>
              {testDrives.map(td => (
                <tr key={td.id}>
                  <td>{td.id}</td>
                  <td>{td.user_email || td.user_id}</td>
                  <td>{td.brand} {td.model}</td>
                  <td>{new Date(td.date).toLocaleDateString()} {td.time}</td>
                  <td>
                    <span className={`${styles.statusBadge} ${styles[td.status]}`}>
                      {td.status === 'pending' ? 'Ожидание' : td.status === 'approved' ? 'Одобрено' : 'Отклонено'}
                    </span>
                  </td>
                  <td>{td.comment || <span style={{ opacity: 0.4 }}>—</span>}</td>
                  <td className={styles.actionsCell}>
                    {td.status === 'pending' && (
                      <>
                        <button className={styles.approveBtn} onClick={() => openTestDriveCommentModal(td.id, 'approved')}>Одобрить</button>
                        <button className={styles.rejectBtn} onClick={() => openTestDriveCommentModal(td.id, 'rejected')}>Отклонить</button>
                      </>
                    )}
                  </td>
                </tr>
              ))}
              {testDrives.length === 0 && (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '2rem' }}>Заявки на тест-драйв отсутствуют</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* ================= ВКЛАДКА: КРЕДИТНЫЕ ПРОДУКТЫ ================= */}
      {activeTab === 'loans' && (
        <div className={styles.tableResponsive}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>ID</th>
                <th>Пользователь (Email)</th>
                <th>Автомобиль</th>
                <th>Сумма кредита</th>
                <th>Срок (мес)</th>
                <th>Платёж / мес</th>
                <th>Статус заявки</th>
                <th>Комментарий банка</th>
                <th>Действия</th>
              </tr>
            </thead>
            <tbody>
              {loans.map(loan => (
                <tr key={loan.id}>
                  <td>{loan.id}</td>
                  <td>{loan.user_email || loan.user_id}</td>
                  <td>{loan.brand} {loan.model}</td>
                  <td>{loan.amount?.toLocaleString()} ₽</td>
                  <td>{loan.term}</td>
                  <td>{Math.round(loan.monthly_payment || 0).toLocaleString()} ₽</td>
                  <td>
                    <span className={`${styles.statusBadge} ${styles[loan.status]}`}>
                      {loan.status === 'pending' ? 'В обработке' : loan.status === 'approved' ? 'Одобрен' : 'Отказ'}
                    </span>
                  </td>
                  <td>{loan.comment || <span style={{ opacity: 0.4 }}>—</span>}</td>
                  <td className={styles.actionsCell}>
                    {loan.status === 'pending' && (
                      <>
                        <button className={styles.approveBtn} onClick={() => openLoanCommentModal(loan.id, 'approved')}>Утвердить</button>
                        <button className={styles.rejectBtn} onClick={() => openLoanCommentModal(loan.id, 'rejected')}>Отклонить</button>
                      </>
                    )}
                  </td>
                </tr>
              ))}
              {loans.length === 0 && (
                <tr>
                  <td colSpan="9" style={{ textAlign: 'center', padding: '2rem' }}>Запросы на кредитные расчеты отсутствуют</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* ================= ВКЛАДКА: УПРАВЛЕНИЕ ПОЛЬЗОВАТЕЛЯМИ ================= */}
      {activeTab === 'users' && user.role === 'admin' && (
        <div className={styles.tableResponsive}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>ID Пользователя</th>
                <th>Электронная почта (Email)</th>
                <th>ФИО Клиента</th>
                <th>Текущий уровень доступа</th>
                <th>Управление правами</th>
                <th>Действия</th>
              </tr>
            </thead>
            <tbody>
              {users.map(u => (
                <tr key={u.id}>
                  <td>{u.id}</td>
                  <td>{u.email}</td>
                  <td>{u.full_name || <span style={{ opacity: 0.4 }}>Не заполнено</span>}</td>
                  <td><strong>{u.role}</strong></td>
                  <td>
                    <select
                      value={u.role}
                      onChange={e => handleRoleChange(u.id, e.target.value)}
                      disabled={u.id === user.id}
                      className={styles.roleSelect}
                      style={{ padding: '0.3rem', borderRadius: '6px' }}
                    >
                      {availableRoles.map(role => (
                        <option key={role} value={role}>{role.toUpperCase()}</option>
                      ))}
                    </select>
                  </td>
                  <td>
                    <button
                      className={styles.deleteBtn}
                      onClick={() => handleDeleteUser(u.id)}
                      disabled={u.id === user.id}
                    >
                      Удалить аккаунт
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ================= МОДАЛЬНОЕ ОКНО: АВТОМОБИЛЬНАЯ ФОРМА ================= */}
      <AnimatePresence>
        {showFormModal && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowFormModal(false)}>
            <motion.div className={styles.modalContent} initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} onClick={e => e.stopPropagation()}>
              <h3>{editingCar ? `Редактирование параметров автомобиля #${editingCar.id}` : 'Добавление нового транспортного средства'}</h3>
              
              {formError && <p className={styles.formGlobalError}>{formError}</p>}

              <form onSubmit={handleSaveCar} className={styles.formScrollable}>
                <div className={styles.formGrid}>
                  
                  <div className={styles.formGroup}>
                    <label>Производитель (Марка) *</label>
                    <div className={`${styles.selectField} ${!carForm.brand ? styles.placeholder : ''}`} onClick={() => setShowBrandModal(true)}>
                      {carForm.brand || '— Нажмите для выбора марки —'}
                    </div>
                    {fieldErrors.brand && <span className={styles.errorText}>{fieldErrors.brand}</span>}
                  </div>

                  <div className={styles.formGroup}>
                    <label>Модель ТС *</label>
                    <div className={`${styles.selectField} ${!carForm.model ? styles.placeholder : ''}`} onClick={() => { if(carForm.brand) setShowModelModal(true); }}>
                      {carForm.model || (carForm.brand ? '— Нажмите для выбора модели —' : 'Сначала выберите марку авто')}
                    </div>
                    {fieldErrors.model && <span className={styles.errorText}>{fieldErrors.model}</span>}
                  </div>

                  <div className={styles.formGroup}>
                    <label>Год выпуска *</label>
                    <input type="number" value={carForm.year} onChange={e => setCarForm(prev => ({ ...prev, year: e.target.value }))} placeholder="Например: 2024" />
                    {fieldErrors.year && <span className={styles.errorText}>{fieldErrors.year}</span>}
                  </div>

                  <div className={styles.formGroup}>
                    <label>Стоимость (руб.) *</label>
                    <input type="number" value={carForm.price} onChange={e => setCarForm(prev => ({ ...prev, price: e.target.value }))} placeholder="Например: 12500000" />
                    {fieldErrors.price && <span className={styles.errorText}>{fieldErrors.price}</span>}
                  </div>

                  <div className={styles.formGroup}>
                    <label>Тип кузова</label>
                    <select value={carForm.body_type} onChange={e => setCarForm(prev => ({ ...prev, body_type: e.target.value }))}>
                      {Object.entries(bodyTypesRussian).map(([key, name]) => (
                        <option key={key} value={key}>{name}</option>
                      ))}
                    </select>
                  </div>

                  <div className={styles.formGroup} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', paddingTop: '1.8rem' }}>
                    <input type="checkbox" id="restylingCheckbox" checked={carForm.restyling} onChange={e => setCarForm(prev => ({ ...prev, restyling: e.target.checked }))} />
                    <label htmlFor="restylingCheckbox" style={{ marginBottom: 0, cursor: 'pointer' }}>Рестайлинг</label>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Объем двигателя (л)</label>
                    <select value={carForm.engine_volume} onChange={e => setCarForm(prev => ({ ...prev, engine_volume: e.target.value }))}>
                      <option value="">Не указано</option>
                      {engineVolumes.map(v => <option key={v} value={v}>{v.toFixed(1)} л</option>)}
                    </select>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Мощность двигателя (л.с.)</label>
                    <select value={carForm.power} onChange={e => setCarForm(prev => ({ ...prev, power: e.target.value }))}>
                      <option value="">Не указано</option>
                      {powers.map(p => <option key={p} value={p}>{p} л.с.</option>)}
                    </select>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Тип топлива</label>
                    <select value={carForm.fuel_type} onChange={e => setCarForm(prev => ({ ...prev, fuel_type: e.target.value }))}>
                      {fuelTypes.map(f => <option key={f} value={f}>{f === 'petrol' ? 'Бензин' : f === 'diesel' ? 'Дизель' : f === 'hybrid' ? 'Гибрид' : 'Электро'}</option>)}
                    </select>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Расход топлива (л/100 км)</label>
                    <input type="number" step="0.1" value={carForm.consumption} onChange={e => setCarForm(prev => ({ ...prev, consumption: e.target.value }))} placeholder="Например: 8.4" />
                  </div>

                  <div className={styles.formGroup}>
                    <label>Тип привода</label>
                    <select value={carForm.drive_type} onChange={e => setCarForm(prev => ({ ...prev, drive_type: e.target.value }))}>
                      {driveTypes.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Коробка передач</label>
                    <select value={carForm.transmission} onChange={e => setCarForm(prev => ({ ...prev, transmission: e.target.value }))}>
                      {transmissions.map(t => (
                        <option key={t} value={t}>
                          {t === 'manual' ? 'Механическая' : t === 'automatic' ? 'Автоматическая' : t === 'robot' ? 'Робот' : 'Вариатор'}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className={styles.formGroup}>
                    <label>Разгон до 100 км/ч (сек)</label>
                    <input type="number" step="0.1" value={carForm.acceleration} onChange={e => setCarForm(prev => ({ ...prev, acceleration: e.target.value }))} placeholder="Например: 3.8" />
                  </div>

                  <div className={styles.formGroup}>
                    <label>Максимальная скорость (км/ч)</label>
                    <input type="number" value={carForm.max_speed} onChange={e => setCarForm(prev => ({ ...prev, max_speed: e.target.value }))} placeholder="Например: 250" />
                  </div>

                  <div className={styles.formGroup}>
                    <label>Дорожный просвет (мм)</label>
                    <input type="number" value={carForm.clearance} onChange={e => setCarForm(prev => ({ ...prev, clearance: e.target.value }))} placeholder="Например: 140" />
                  </div>

                  <div className={styles.formGroup}>
                    <label>Количество мест</label>
                    <select value={carForm.seats} onChange={e => setCarForm(prev => ({ ...prev, seats: e.target.value }))}>
                      {seatOptions.map(s => <option key={s} value={s}>{s} мест</option>)}
                    </select>
                  </div>

                </div>

                <div className={styles.formGroupFull} style={{ marginTop: '1rem' }}>
                  <label>Текстовое описание автомобиля</label>
                  <textarea value={carForm.description} onChange={e => setCarForm(prev => ({ ...prev, description: e.target.value }))} placeholder="Укажите комплектацию, особенности и состояние автомобиля..." rows="3" style={{ width: '100%', padding: '0.5rem', borderRadius: '8px', border: '1px solid rgba(0,0,0,0.15)' }}></textarea>
                </div>

                <div className={styles.formGroupFull} style={{ marginTop: '1rem' }}>
                  <label>Изображение автомобиля</label>
                  <input type="file" accept="image/*" ref={fileInputRef} onChange={handleSingleFileChange} style={{ display: 'none' }} />
                  <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
                    <button type="button" className={styles.uploadBtn} onClick={() => fileInputRef.current.click()} disabled={uploading}>
                      {uploading ? 'Загрузка файла...' : 'Выбрать файл фотографии'}
                    </button>
                    <input type="text" value={carForm.image_url} onChange={e => setCarForm(prev => ({ ...prev, image_url: e.target.value }))} placeholder="Или укажите прямой URL изображения" style={{ flex: 1 }} />
                  </div>
                  {carForm.image_url && (
                    <div className={styles.imagePreviewWrapper} style={{ marginTop: '1rem' }}>
                      <img src={getImageUrl(carForm.image_url)} alt="Preview" style={{ maxHeight: '120px', borderRadius: '8px', objectFit: 'cover' }} />
                    </div>
                  )}
                </div>

                <div className={styles.modalActions} style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '2rem' }}>
                  <button type="button" className={styles.cancelBtn} onClick={() => setShowFormModal(false)}>Отмена</button>
                  <button type="submit" className={styles.submitBtn} disabled={submitting}>
                    {submitting ? 'Сохранение данных...' : 'Сохранить изменения'}
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ================= МОДАЛЬНОЕ ОКНО: ВЫБОР МАРКИ ================= */}
      <AnimatePresence>
        {showBrandModal && (
          <motion.div className={styles.brandOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowBrandModal(false)}>
            <motion.div className={styles.brandModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} onClick={e => e.stopPropagation()}>
              <div className={styles.brandModalHeader}>
                <h4>Выберите марку автомобиля</h4>
                <button type="button" onClick={() => setShowBrandModal(false)} className={styles.closeBtn}>✕</button>
              </div>
              <input type="text" placeholder="Поиск марки по названию..." value={brandSearch} onChange={e => setBrandSearch(e.target.value)} className={styles.brandSearchInput} autoFocus />
              <div className={styles.brandList}>
                {filteredBrands.map(brand => (
                  <button key={brand} type="button" className={`${styles.brandItem} ${brand === carForm.brand ? styles.brandItemActive : ''}`} onClick={() => selectBrand(brand)}>
                    {brand}
                  </button>
                ))}
                {filteredBrands.length === 0 && <p className={styles.noModels}>Марки с таким названием отсутствуют</p>}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ================= МОДАЛЬНОЕ ОКНО: ВЫБОР МОДЕЛИ ================= */}
      <AnimatePresence>
        {showModelModal && (
          <motion.div className={styles.modelOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowModelModal(false)}>
            <motion.div className={styles.modelModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} onClick={e => e.stopPropagation()}>
              <div className={styles.modelModalHeader}>
                <h4>Выберите модель для {carForm.brand}</h4>
                <button type="button" onClick={() => setShowModelModal(false)} className={styles.closeBtn}>✕</button>
              </div>
              <input type="text" placeholder="Поиск модели по кодовому названию..." value={modelSearch} onChange={e => setModelSearch(e.target.value)} className={styles.modelSearchInput} autoFocus />
              <div className={styles.modelList}>
                {filteredModels.map(model => (
                  <button key={model} type="button" className={`${styles.modelItem} ${model === carForm.model ? styles.modelItemActive : ''}`} onClick={() => selectModel(model)}>
                    {model}
                  </button>
                ))}
                {filteredModels.length === 0 && <p className={styles.noModels}>Подходящие модификации моделей отсутствуют</p>}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ================= МОДАЛЬНОЕ ОКНО КОММЕНТАРИЯ КРЕДИТА ================= */}
      <AnimatePresence>
        {loanCommentModal && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <motion.div className={styles.commentModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }}>
              <h4>{currentAction === 'approved' ? 'Одобрение кредитной заявки' : 'Отклонение кредитной заявки'}</h4>
              <p>Вы можете оставить официальное сопроводительное решение или комментарий для клиента:</p>
              <textarea value={loanComment} onChange={e => setLoanComment(e.target.value)} placeholder="Например: Кредит одобрен ПАО ВТБ под 11.4% годовых..." rows="4" style={{ width: '100%', padding: '0.5rem', borderRadius: '6px', margin: '1rem 0' }}></textarea>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem' }}>
                <button className={styles.cancelBtn} onClick={() => setLoanCommentModal(false)}>Отмена</button>
                <button className={styles.submitBtn} onClick={handleLoanStatusSubmit}>Подтвердить решение</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ================= МОДАЛЬНОЕ ОКНО КОММЕНТАРИЯ ТЕСТ-ДРАЙВА ================= */}
      <AnimatePresence>
        {testDriveCommentModal && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <motion.div className={styles.commentModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }}>
              <h4>{currentTestDriveAction === 'approved' ? 'Подтверждение записи на тест-драйв' : 'Отмена записи на тест-драйв'}</h4>
              <p>Укажите сервисный комментарий для отправки пользователю (например, имя назначенного менеджера или причину отказа):</p>
              <textarea value={testDriveComment} onChange={e => setTestDriveComment(e.target.value)} placeholder="Например: Ждем вас в автосалоне. Ваш персональный менеджер: Алексей." rows="4" style={{ width: '100%', padding: '0.5rem', borderRadius: '6px', margin: '1rem 0' }}></textarea>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem' }}>
                <button className={styles.cancelBtn} onClick={() => setTestDriveCommentModal(false)}>Отмена</button>
                <button className={styles.submitBtn} onClick={handleTestDriveStatusSubmit}>Выдать статус</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

    </motion.div>
  );
};

export default AdminPanel;
